func TestNewAutoSignerPath(t *testing.T) {
	t.Run("should succeed when no key exists", func(t *testing.T) {
		_, err := newAutoSignerPath(
			filepath.Join(t.TempDir(), DefaultNotaryKey),
			"",
			sshx.UnsafeNewKeyGen(),
		)
		require.NoError(t, err)
	})

	t.Run("should fail when unable to write to disk", func(t *testing.T) {
		if userx.CurrentUserOrDefault(userx.Root()).Uid == "0" {
			log.Println("ROOT USER")
			return
		}
		tmp := t.TempDir()
		os.Stat(tmp)
		require.NoError(t, os.Chmod(tmp, 0100))
		_, err := newAutoSignerPath(
			filepath.Join(tmp, DefaultNotaryKey),
			"",
			sshx.UnsafeNewKeyGen(),
		)
		require.Error(t, err)
	})
}

func TestErrUnauthorizedKeyError(t *testing.T) {
	t.Run("contains the public key path", func(t *testing.T) {
		err := ErrUnauthorizedKey{}
		require.Contains(t, err.Error(), PublicKeyPath())
	})

	t.Run("contains instruction to give file to authorized user", func(t *testing.T) {
		err := ErrUnauthorizedKey{}
		require.Contains(t, err.Error(), "your key is unauthorized")
		require.Contains(t, err.Error(), "please give the following file to an authorized user")
	})

	t.Run("matches expected format", func(t *testing.T) {
		err := ErrUnauthorizedKey{}
		expected := fmt.Sprintf(`your key is unauthorized and will need to be added by an authorized user.
please give the following file to an authorized user "%s".`, PublicKeyPath())
		require.Equal(t, expected, err.Error())
	})
}
